// stableStringify — deterministic JSON serialization with recursively sorted
// object keys so the same logical state always produces the same string.
// Arrays keep their order (order is meaningful). undefined/functions are
// dropped by JSON semantics; this mirrors JSON.stringify value handling.
function stableStringify(value) {
  return JSON.stringify(sortKeysDeep(value));
}

function sortKeysDeep(value) {
  if (Array.isArray(value)) {
    return value.map(sortKeysDeep);
  }
  if (value && typeof value === 'object') {
    // A plain {} silently drops JSON's own "__proto__" key through its
    // inherited setter, producing a hash that no backend can reproduce.
    var out = Object.create(null);
    Object.keys(value).sort().forEach(function (k) {
      out[k] = sortKeysDeep(value[k]);
    });
    return out;
  }
  return value;
}

// Synchronous hash for the v3 liquid compiler, which has a synchronous
// manifest API. It uses the exact stable JSON and pure-JS SHA-256 fallback
// already used by the asynchronous air sourceProject exporter.
function projectContentHashSync(state) {
  return sha256HexJS(utf8Bytes(stableStringify(canonicalProjectForHash(state || {}))));
}

// cfdproj v5: a live project carries its time-variable fields materialised
// at the playhead; on disk they exist only in `transient.tracks`. The hash
// is of the disk form, so a live project, a reopened file and a copy
// materialised at another time all bind to the same content.
function canonicalProjectForHash(state) {
  var tr = state && state.transient;
  if (!tr || !Array.isArray(tr.tracks) || !tr.tracks.length) return state;
  var T = (typeof window !== 'undefined' && window.cfdprojTransient) ||
    (typeof require === 'function' ? require('./cfdproj_transient.js') : null);
  if (!T) throw new Error('cfdrun_export: cfdproj_transient.js is required to hash a v5 project');
  return T.stripTrackedFields(JSON.parse(JSON.stringify(state)));
}

function enumerateTargets(model, entry) {
  const out = [];
  const segs = parse(entry.path);
  walk(model, segs, 0, [], model, entry.where, (parent, key, bindings) => {
    const value = parent[key];
    if (value !== undefined && value !== null) out.push({ target: bindings.join('/'), value });
    else if (entry.createWithDefault) out.push({ target: bindings.join('/'), value: entry.default });
  });
  if (!out.length && entry.createWithDefault && segs.every((s) => s.kind === 'key')) {
    out.push({ target: '', value: entry.default });
  }
  return out;
}

/** Parent object and key of (entry, target); plain-key parents are created when `create`. */
function locate(model, entry, target, create) {
  const segs = parse(entry.path);
  const vals = target === '' ? [] : String(target).split('/');
  let obj = model;
  let vi = 0;
  for (let i = 0; i < segs.length - 1; i++) {
    const s = segs[i];
    if (obj == null || typeof obj !== 'object') return null;
    if (s.kind === 'key') {
      if (obj[s.key] == null) { if (!create) return null; obj[s.key] = {}; }
      obj = obj[s.key];
    } else if (s.kind === 'var') {
      const k = vals[vi++];
      obj = Array.isArray(obj) ? obj[Number(k)] : obj[k];
    } else if (s.kind === 'idsel') {
      const id = vals[vi++];
      obj = (Array.isArray(obj[s.key]) ? obj[s.key] : []).find((el) => el && String(el.id) === id);
    } else {
      const rest = Object.assign({}, entry, { path: segs.slice(i + 1).map(fmt).join('.') });
      const restTarget = vals.slice(vi).join('/');
      for (const k of Object.keys(obj)) {
        const hit = locate(obj[k], rest, restTarget, false);
        if (hit) return hit;
      }
      return null;
    }
  }
  if (obj == null || typeof obj !== 'object') return null;
  return { parent: obj, key: segs[segs.length - 1].key };
}
function getAt(model, entry, target) {
  const h = locate(model, entry, target, false);
  return h ? h.parent[h.key] : undefined;
}
function setAt(model, entry, target, value) {
  const h = locate(model, entry, target, true);
  if (!h) throw new Error(`cfdproj_transient: no field for ${entry.key} target "${target}"`);
  h.parent[h.key] = value;
}
function deleteAt(model, entry, target) {
  const h = locate(model, entry, target, false);
  if (h) delete h.parent[h.key];

/** A t = 0 track for every registry instance whose field is present (or defaulted). */
function tracksFromFields(doc) {
  return [...snapshotTargets(doc).values()].map(({ uid, entry, target, value }) =>
    ({ modelUid: uid, param: entry.key, target, keyframes: [{ t: 0, value: Number(value) }] }));
}
function modelIndex(doc) {
  const m = new Map();
  forEachModel(doc, (bucket, uid, model) => m.set(uid, model));
  return m;
}
function tracksOf(doc) { return (doc && doc.transient && Array.isArray(doc.transient.tracks)) ? doc.transient.tracks : []; }

/** In place: every tracked field := its track's value at t. */
function materializeAt(doc, t) {
  const idx = modelIndex(doc);
  for (const trk of tracksOf(doc)) {
    const model = idx.get(trk.modelUid);
    const e = entryOf(trk.param);
    if (model && e && trk.keyframes && trk.keyframes.length) setAt(model, e, trk.target, valueAt(trk.keyframes, t));
  }
  return doc;
}
/** In place: delete every tracked field (what is written to disk). */
function stripTrackedFields(doc) {
  const idx = modelIndex(doc);
  for (const trk of tracksOf(doc)) {
    const model = idx.get(trk.modelUid);
    const e = entryOf(trk.param);
    if (model && e) deleteAt(model, e, trk.target);
  }
  return doc;

function emit(documentChanged = false) {
  if (documentChanged) documentEditRevision += 1
  stateRevision += 1
  listeners.forEach((fn) => fn())
}

export function subscribe(fn: Listener): () => void {
  listeners.add(fn)
  return () => {
    listeners.delete(fn)
  }
}

export function getProject(): CfdProject | null {
  return state.project

export function logAction(action: string, detail = '') {
  logOperation(action, detail)
  emit()
}

export function markSaved(path: string) {
  state = { ...state, path, dirty: false }
  logOperation('saveProject', path)
  emit()
}

export function notifyLiveEdit(action = 'liveEdit', detail = '') {
  if (!state.project) return
  // Off t = 0 the scene is frozen for in-place edits too: judged against the
  // last accepted state, a changed scene is put back whole (as `edit` refuses).
  if (frozenRef && frozenStatic !== null && transientModel().staticText(state.project) !== frozenStatic) {
    state = { ...state, project: transientModel().materializeAt(cloneProject(frozenRef), playhead) }
    refuse(action, { ok: false, reason: 'static', detail: [] })
    emit()
    return
  }
  // Legacy code mutated the live object in place: fold any time-variable field
  // it touched back into the tracks, or the next materialise would undo it.
  transientModel().syncFieldsToTracks(state.project, playhead)
  lastRejection = null
  state = { ...state, dirty: true }
  refreshFrozenRef()
  if (action !== 'liveEdit') logOperation(action, detail)
  emit(true)
}

const degraded=useRef(false)
const interactionAllowed=useRef(false)
interactionAllowed.current=mode==='ov'&&ready&&!returning&&!degraded.current
const projectUid=useRef<string|null>(project?.uid??null)
projectUid.current=project?.uid??null
const hasOverlay=useRef(false)
const session=useRef(0)
useSyncExternalStore(store.subscribe,store.revision)
const sample=useSyncExternalStore(subscribeResultSample,selectedResultSample)
const visualRevision=useSyncExternalStore(subscribeResultSample,resultRenderRevision)
const displayRevision=useSyncExternalStore(subscribeClosedCabinetDisplay,leafDisplayRevision)
const previewRevision=useSyncExternalStore(subscribeMeshPreview,currentMeshOverlayRevision)
const layerRevision=useSyncExternalStore(subscribeResultLayerRevision,resultLayerRevision)
const initialSent=useRef('')
const sentProjectUid=useRef('')
const timeSeconds=selectedResultTime()
